def check_solutions(p, a_max):
    solutions = []
    for a in range(1, a_max + 1):
        for x in range(1, 15):
            b = p**x - a**(p-1)
            if b > a:
                # Check if b**(p-1) + a is a power of p
                val = b**(p-1) + a
                y = 0
                temp_val = val
                while temp_val > 1 and temp_val % p == 0:
                    temp_val //= p
                    y += 1
                if temp_val == 1 and y > 0:
                    solutions.append((p, a, b))
    return solutions

